"결과 상담실에서 의사가 수치 몇 개에 동그라미를 치며 운동을 늘리라고 했고, 수첩에 그대로 받아 적었다":"在結果諮詢室裡，醫生圈了幾個數值要我多運動，我照著記在筆記本上",
