"공 던지기를 배우던 날 공이 엉뚱하게 날아가 화단 덤불 속으로 들어가 버려 찾느라 시간이 다 갔다":"學丟球那天球飛歪了，掉進花壇灌木叢裡，找球找到時間都耗光了",
"공 차다가 신발 밑창이 쩍 벌어져, 그날 놀이는 맨발로 절뚝이며 돌아오는 걸로 끝났다":"踢球時鞋底整個裂開，那天的玩耍就以光著腳一拐一拐走回來收場",
