"공공 일자리에 뽑혀 아침마다 조끼를 걸치고 공원 쓰레기를 주우며 지나는 이웃과 인사를 나눴다":"被選進公共工作，每天早上套上背心撿公園垃圾，和路過的鄰居打招呼",
