"공을 빌려 달라고 졸졸 따라다녔지만 끝내 순서가 오지 않아 담벼락만 바라보다 돌아왔다":"一直跟在後面吵著要借球，卻始終輪不到，看著牆壁發了一會兒呆就回家了",
"공을 차다가 이웃집 담 너머로 넘겨 버려서, 그날은 문 앞에서 한참 서성이기만 했다":"踢球時踢過了鄰居家的圍牆，那天只能在門口徘徊了好久",
