"기본기":"基本功",
"기술을 전수한다":"傳授技術",
"기차 시간을 한 시간 착각해서 승강장에서 문이 닫히는 걸 바라보고, 다음 차를 기다리며 첫 일정을 건너뛰었다":"把火車時間記錯了一個小時，在月臺上眼睜睜看著車門關上，等下一班車，跳過了第一個行程",
