"이불 속에서 손전등으로 책을 읽다가 건전지가 나갈 때까지 마지막 장을 놓지 못했다":"在被窩裡用手電筒看書，直到電池沒電，都放不下最後一章",
"이불 속에서 손전등을 켜고 물고기 그림책을 펴 보다가 파란 바다 쪽에서 오래 머물렀다":"在被窩裡打開手電筒翻看魚的繪本，在藍色海洋那一頁停留了很久",
"이불 속에서 휴대폰을 잠깐 본다는 게 두 시간이 훌쩍 지나, 일어났을 때 머리만 더 무거웠다":"在被窩裡只想看一下手機，兩個小時一下子過去，起床時只覺得頭更沉了",
"이불을 둘러쓰고 동굴 탐험대가 되어, 손전등 하나로 방 안 구석구석을 비추고 다녔다":"披著棉被當洞窟探險隊，用一支手電筒照亮房間的每個角落",
"이사 가는 날 짐 사이에서 들고 나온 소설을 이삿짐 트럭 안에서 끝까지 읽었다":"搬家那天從行李堆裡拿出來的小說，在搬家貨車裡一路讀到最後",
"이사 짐을 풀다 나온 아이 적 그림책을 바닥에 주저앉아 쪽마다 넘겨 보았다":"拆搬家行李時翻出小時候的繪本，直接坐在地板上一頁一頁翻看",
"이어폰 없이 걸으며 새소리를 하나하나 구분하려 해 보았는데 세 가지까지 이름을 붙일 수 있었다":"不戴耳機邊走邊試著分辨鳥叫聲，最多能叫出三種的名字",
"이어폰에서 흘러나온 빠른 노래에 발을 맞춰, 운동장 트랙을 숨이 차오를 때까지 여덟 바퀴 돌았다":"耳機裡傳出快節奏的歌，配合著節拍在操場跑道上跑了八圈，跑到喘不過氣",
"이웃 노인이 내가 쓰던 연장을 한번 만져 보더니, 이렇게 쓰는 거냐며 어설프게 흉내를 냈다":"鄰居老人摸了摸我用過的工具，問是不是這樣用，笨拙地模仿了起來",
"이웃 농사일을 틈틈이 도와 주고 품삯 대신 받은 자루를 부엌 한쪽에 가지런히 쌓아 두었다":"一有空就幫鄰居做農活，把當作工錢收到的麻袋整齊堆在廚房一角",
"이웃 동네 사람들과 땀에 젖은 첫 연습 경기를 뛰고, 끝난 뒤 둘러앉아 먹은 얼음물이 달았다":"與鄰村的人們打了第一場汗流浹背的練習賽，結束後圍坐著喝的冰水特別甜",
"이웃 마을로 떠난 동료에게 안부를 물었더니 새 일터의 창가 풍경을 소상히 들려주었다":"問候搬到鄰村的同事，他詳細說起新工作場所窗邊的風景",
"이웃 사람 손을 잡아 연장 쥐는 법을 바로잡아 주자, 고개를 끄덕이며 한 번 더 해 보았다":"握著鄰居的手矯正他拿工具的方法，他點點頭又試了一次",
"이웃 아이가 가져온 부침개를 식탁에 올려놓고 둘러앉아 먹다 보니 한 접시가 금세 비었다":"鄰居孩子帶來的煎餅放上餐桌，圍著吃，一盤很快就空了",
"이웃 아주머니가 가져온 낡은 악기를 같이 손봐 주고, 소리가 나던 순간 서로 얼굴을 쳐다보았다":"和鄰居阿姨一起修理她帶來的舊樂器，發出聲音的那一刻，兩人互相對看",
"이웃 청년이 찾아와 고장 난 물건을 같이 고쳐 보자고 해서, 손끝을 맞대고 요령을 보여 주었다":"鄰居的年輕人來找我，說想一起修壞掉的東西，我們指尖相對示範訣竅",
"이웃과 마당 평상에 걸터앉아 삶은 감자를 나누며 아이들 크는 이야기로 해가 넘어갔다":"與鄰居坐在院子的矮床上分著煮熟的馬鈴薯，聊著孩子長大的事，太陽就下山了",
"이웃이 부드럽게 푹 끓인 죽을 한 숟갈씩 나눠 주고 내 그릇이 비는 걸 지켜보았다":"鄰居分給我一匙一匙熬得軟爛的粥，看著我的碗見底",
"이웃집 손자가 찾아와 같이 작업대에 앉아 오래된 요령을 하나씩 가르쳤다":"鄰居家的孫子來找我，一起坐在工作台前，把古老的訣竅一個一個教給他",
"이웃집 전화를 빌려 장터 소식을 물어 놓고 한참 수화기를 쥔 채 바깥 마당을 내다보았다":"借用鄰居家的電話打聽市集的消息，握著話筒好久，望著外面的院子",
"이제는 눈을 감고도 순서대로 공정을 밟는다고 반장이 말했고, 내 이름이 처음으로 작업표 가운데 칸에 올랐다":"組長說我現在閉著眼睛也能依序完成工序，我的名字第一次出現在工作表的中間欄",
"일 생각을 잠깐 접고 놀이공원 줄에 서서, 비명 소리가 들릴 때마다 괜히 손바닥이 간지러웠다":"暫時放下工作的念頭，在遊樂園排隊，每次聽到尖叫聲，手掌就莫名發癢",
"일손을 하루 놓고 마루에 앉아 식은 보리차를 홀짝이며 앞산 그늘이 천천히 밭으로 내려오는 걸 보았다":"放下一天的工作坐在地板上，啜飲著涼掉的麥茶，看著前山的陰影慢慢爬下田地",
"일요일 아침 창문을 모두 열고 이불을 털어 널었더니, 방 안에 해 냄새가 가득 찼다":"星期天早上把窗戶全部打開，拍打曬起棉被，房間裡充滿了陽光的味道",
"일요일 정오 식탁에 식구들이 번갈아 앉아 국과 밥을 나르며 한 주의 이야기를 꺼내 놓았다":"星期天中午，家人輪流坐上餐桌，端湯端飯，聊起這一週的事",
"일을 끝내고 나서 받은 봉투에 약속한 시간의 절반만 들어 있어서, 확인해 달라는 말을 꺼내지 못했다":"工作結束後領到的信封裡只有約定時間的一半，我說不出口要對方確認",
"일이 끝난 저녁 동료와 길가 포장마차 의자에 앉아 김 나는 국물을 나눠 먹으며 하루를 털어 냈다":"工作結束的傍晚，與同事坐在路邊攤的椅子上分食冒著熱氣的湯，抖落了一天的疲憊",
"일이 늦게 끝나 식구들이 기다리다 먼저 먹은 뒤라서 혼자 식은 밥에 물을 말아 먹었다":"工作很晚才結束，家人等不及先吃完了，我一個人把冷飯泡水吃掉",
"일터 인근 독서 모임에서 낯선 이가 내 의견에 고개를 끄덕여 주어 끝나고 오래 이야기가 이어졌다":"在公司附近的讀書會上，有個陌生人對我的意見點頭，結束後聊了很久",
"읽다 만 그림책을 식탁에 펼쳐 둔 채 급한 일에 불려 나가 끝내 다음 쪽을 못 넘겼다":"把讀到一半的繪本攤在餐桌上，被急事叫出去，終究沒能翻到下一頁",
"읽던 소설책이 어디로 갔나 한참 찾았더니 빨래 바구니 밑에서 구겨진 채 나왔다":"找了好久讀到一半的小說跑哪去了，最後在洗衣籃底下找到，皺巴巴的",
"읽던 책에 끼워 둔 책갈피가 빠져 버려서 어디까지 읽었는지 찾느라 한 시간을 보냈다":"夾在書裡的書籤掉了，為了找讀到哪裡，花了一個小時",
