"입문":"入門",
"자식이 챙겨 준 작은 가방에 약통과 모자를 넣고, 난생처음 비행기 창가 자리에 앉아 구름을 내려다보았다":"把藥盒和帽子放進孩子準備的小包包，生平第一次坐在飛機靠窗的位子，俯視雲海",
