"저녁 강좌 교실에서 수강생들 앞에 서서 오늘의 요령을 칠판에 한 줄씩 적어 나갔다":"在夜間課程的教室站在學員面前，把今天的訣竅一行一行寫在黑板上",
"저녁 공유 차량 운행을 하루 세 시간씩 해서, 지도 앱을 보며 골목을 돌고 나면 지갑이 조금 두꺼워졌다":"晚上開共乘車，每天三小時，看著導航在巷子裡繞完一圈，錢包稍微厚了一點",
"저녁 노을을 등지고 그림자와 경주를 하며 집 앞 길을 끝에서 끝까지 달렸다":"背對晚霞與影子賽跑，從家門前的路一頭跑到另一頭",
"저녁 먹고 말없이 둑길을 걸었고, 개구리 소리가 혼자인 걸음 사이를 채워 주었다":"吃完晚飯默默走在堤防路上，青蛙的叫聲填滿了獨自一人的腳步之間",
