"저녁 산책길에 휴대폰을 꺼내 오랫동안 못 들은 목소리의 번호를 눌렀고 첫 신호음에 바로 받았다":"晚間散步時拿出手機，撥了好久沒聽到的聲音的號碼，第一聲嘟聲就被接起",
